def day(n, week, title, aim, rule, words, listen, copy, exercise, answers, recall):
    return {
        "day": n, "week": week, "title": title, "aim": aim, "rule": rule,
        "words": [{"en": a, "vi": b} for a, b in words],
        "listen": [{"en": a, "vi": b} for a, b in listen],
        "copy": copy, "exercise": exercise, "answers": answers, "recall": recall,
    }

P = lambda *pairs: list(pairs)

